def solve_polycarp_problem(n, k, difficulties):
    prefix_max = [0] * (n + 1)
    for i in range(n):
        prefix_max[i + 1] = max(prefix_max[i], difficulties[i])

    dp = [[0] * (k + 1) for _ in range(n + 1)]
    path = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dp[i][1] = prefix_max[i]
        path[i][1] = i

    for j in range(2, k + 1):
        for i in range(j, n + 1):
            for x in range(j - 1, i):
                profit = dp[x][j - 1] + (prefix_max[i] - prefix_max[x])
                if profit > dp[i][j]:
                    dp[i][j] = profit
                    path[i][j] = x

    result = []
    i, j = n, k
    while j > 0:
        result.append(path[i][j] - path[i - path[i][j]][j - 1])
        i = path[i][j]
        j -= 1

    return dp[n][k], result[::-1]

def main():
    n, k = map(int, input().split())
    difficulties = list(map(int, input().split()))

    max_profit, distribution = solve_polycarp_problem(n, k, difficulties)

    print(max_profit)
